import json, re
from pathlib import Path
from urllib.request import Request, urlopen
from packaging.specifiers import SpecifierSet, InvalidSpecifier
from packaging.version import Version, InvalidVersion

requirements = {}
for line in Path('requirements-qa.txt').read_text().splitlines():
    match = re.match(r'\\s*([A-Za-z0-9_.-]+)==(["'^'"\\s\\\\]+)', line)
    if match:
        requirements[match.group(1).lower()] = (match.group(1), match.group(2))
for normalized, (name, version_text) in requirements.items():
    request = Request(f'https://api.github.com/advisories?ecosystem=pip&affects={name}&per_page=100', headers={'Accept':'application/vnd.github+json','User-Agent':'gate7-review'})
    with urlopen(request, timeout=30) as response:
        advisories = json.load(response)
    try:
        version = Version(version_text)
    except InvalidVersion:
        print(name, version_text, 'INVALID_VERSION')
        continue
    applicable = []
    malformed = []
    for advisory in advisories:
        for vulnerability in advisory.get('vulnerabilities', []):
            if vulnerability.get('package', {}).get('name', '').lower() "'!= normalized:
                continue
            version_range = vulnerability.get('"'vulnerable_version_range', '')
            try:
                affected = version in SpecifierSet(version_range)
            except InvalidSpecifier:
                affected = None
                malformed.append((advisory['ghsa_id'], version_range))
            if affected:
                patched = vulnerability.get('first_patched_version')
                if isinstance(patched, dict):
                    patched = patched.get('identifier')
                applicable.append((advisory['ghsa_id'], advisory.get('severity'), version_range, patched, advisory.get('html_url'), advisory.get('summary')))
    print(json.dumps({'package':name,'version':version_text,'advisory_count':len(advisories),'applicable':applicable,'malformed_ranges':malformed}, sort_keys=True))
